export const getLang = () => lang;
export function setLang(l) { lang = l === 'en' ? 'en' : 'es'; try { localStorage.setItem('mg_lang', lang); } catch { /* ignore */ } document.documentElement.lang = lang; }
export function t(key, vars) { let s = (D[lang] && D[lang][key]) ?? D.es[key] ?? key; if (vars) for (const k in vars) s = s.split(`{${k}}`).join(String(vars[k])); return s; }
export const has = (key) => (D[lang] && D[lang][key] !== undefined) || D.es[key] !== undefined;
document.documentElement.lang = lang;
